import {mkdir,writeFile} from 'node:fs/promises';import {createHash} from 'node:crypto';
import {ProgramBuilder,audioTrack,audioSourceLoopRegion,instruction} from 'galbox-sdk/port-kit';import {createReleaseManifest,inspectResource} from 'galbox-sdk/release';import {encodeWire} from 'galbox-sdk/wire';
const rate=8000,frames=rate*4,data=Buffer.alloc(44+frames*2);data.write('RIFF');data.writeUInt32LE(data.length-8,4);data.write('WAVEfmt ',8);data.writeUInt32LE(16,16);data.writeUInt16LE(1,20);data.writeUInt16LE(1,22);data.writeUInt32LE(rate,24);data.writeUInt32LE(rate*2,28);data.writeUInt16LE(2,32);data.writeUInt16LE(16,34);data.write('data',36);data.writeUInt32LE(frames*2,40);for(let n=0;n<frames;n++)data.writeInt16LE(Math.round(Math.sin(n/rate*Math.PI*440)*1000),44+n*2);
const b=new ProgramBuilder({gameId:'live-loop-link',release:'v1',entry:'main'}),a=b.asset('audio',{id:'tone',path:'tone.wav',mime:'audio/wav',sha256:createHash('sha256').update(data).digest('hex'),playback:'element'}),page=(at:string)=>instruction('text.page',{at,textId:at,revision:'v1',speaker:'',content:at});
b.function({id:'enable',entry:'link',layout:1,params:[],locals:[],returns:'void',code:[audioSourceLoopRegion('link','tone',{fromFrame:4800,toFrame:1600,sampleRate:rate,enabled:true}),instruction('control.return',{at:'enabled-return'})]});
b.function({id:'main',entry:'music',layout:1,params:[],locals:[],returns:'void',code:[audioTrack('music','tone',a,{channel:'bgm',loop:true,gain:.1,restore:'replay'}),page('before'),instruction('control.call',{at:'enable-call',function:'enable',args:[]}),page('enabled'),audioSourceLoopRegion('off','tone',{fromFrame:4800,toFrame:1600,sampleRate:rate,enabled:false}),page('disabled'),audioSourceLoopRegion('outside','tone',{fromFrame:80000,toFrame:1600,sampleRate:rate,enabled:true}),page('invalid'),instruction('control.end',{at:'end'})]});
const program=b.build(),resources=[inspectResource(program.assets[0]!,data,bytes=>new TextDecoder().decode(bytes))],release=await createReleaseManifest({program,series:'1',resources},{async sha256(s){return createHash('sha256').update(s).digest('hex');}}),root='tests/player-app/public/loop-region';await mkdir(root,{recursive:true});await writeFile(root+'/tone.wav',data);await writeFile(root+'/program.json',JSON.stringify(program));await writeFile(root+'/release.pb',encodeWire('ReleaseManifest',release));
